CREATE TABLE IF NOT EXISTS bills(bill_id BIGSERIAL PRIMARY KEY,branch_id BIGINT NOT NULL,booking_id BIGINT NOT NULL UNIQUE,customer_id BIGINT NOT NULL,room_charges NUMERIC(14,2) NOT NULL DEFAULT 0,restaurant_charges NUMERIC(14,2) NOT NULL DEFAULT 0,tax_amount NUMERIC(14,2) NOT NULL DEFAULT 0,discount NUMERIC(14,2) NOT NULL DEFAULT 0,final_amount NUMERIC(14,2) NOT NULL DEFAULT 0,bill_status VARCHAR(40) NOT NULL,bill_type VARCHAR(40) NOT NULL,payment_status VARCHAR(40) NOT NULL,invoice_url VARCHAR(500),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS bill_charges(charge_id BIGSERIAL PRIMARY KEY,bill_id BIGINT NOT NULL REFERENCES bills(bill_id) ON DELETE CASCADE,charge_type VARCHAR(40) NOT NULL,description VARCHAR(500) NOT NULL,reference_id VARCHAR(100),amount NUMERIC(14,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS invoices(invoice_id BIGSERIAL PRIMARY KEY,bill_id BIGINT NOT NULL UNIQUE REFERENCES bills(bill_id) ON DELETE CASCADE,invoice_number VARCHAR(80) NOT NULL UNIQUE,invoice_status VARCHAR(40) NOT NULL,invoice_url VARCHAR(500),generated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS tax_configurations(tax_configuration_id BIGSERIAL PRIMARY KEY,branch_id BIGINT UNIQUE,tax_rate NUMERIC(8,4) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
